```python
from urllib.parse import urlsplit


def load_spam_domains(path):
    """Read the list once at startup and return an immutable set."""
    domains = set()
    with open(path, encoding="utf-8") as f:
        for line in f:
            line = line.strip().lower()
            if line and not line.startswith("#"):
                domains.add(line)
    return frozenset(domains)


def is_spam_referrer(referrer, spam_domains):
    """True if the referrer host or any parent domain is listed."""
    if not referrer:
        return False
    try:
        host = urlsplit(referrer.strip()).hostname
    except ValueError:
        return False
    if not host:
        return False

    parts = host.lower().rstrip(".").split(".")
    # a.b.spam.example -> a.b.spam.example, b.spam.example, spam.example, example
    return any(".".join(parts[i:]) in spam_domains for i in range(len(parts)))
```

Load the set once and pass it in on every hit:

