diff only. todo scanner, runs in our pre-commit hook over every staged file (stdin, one call per file). tags come from argv.

```python
import re
import sys

def scan(lines, tags, owner=None):
    hits = []
    for lineno, line in enumerate(lines, 1):
        m = re.search(r"(?:#|//)\s*(" + "|".join(map(re.escape, tags)) + r")(?:\((\w+)\))?:\s*(.*)", line)
        if not m:
            continue
        if owner and m.group(2) != owner:
            continue
        hits.append((lineno, m.group(1), m.group(3).strip()))
    return hits

def main(argv):
    tags = argv[1].split(",")
    for lineno, tag, text in scan(sys.stdin, tags):
        print(f"{lineno}:{tag}:{text}")

if __name__ == "__main__":
    main(sys.argv)
```

