```python
import struct
import time

# BLE sensors in the warehouse, keyed by MAC
SENSORS = {
    "C4:7C:8D:6A:11:02": {"room": "cold-room-1", "kind": "temp_hum"},
    "C4:7C:8D:6A:11:7F": {"room": "cold-room-2", "kind": "temp_hum"},
    "E8:31:CD:0F:42:9A": {"room": "loading-dock", "kind": "door"},
}

last_seen = {}
unknown_adverts = 0


def decode_temp_hum(data):
    temp, hum, batt = struct.unpack("<hHB", data[:5])
    return {"temp_c": temp / 100, "humidity": hum / 100, "battery": batt}


def decode_door(data):
    return {"open": bool(data[0]), "battery": data[1]}


DECODERS = {"temp_hum": decode_temp_hum, "door": decode_door}


def take_unknown_count():
    """Return foreign adverts seen since the last call and reset the counter."""
    global unknown_adverts
    count, unknown_adverts = unknown_adverts, 0
    return count


def handle_advert(mac, rssi, data, publish):
    """Called by the scanner for every BLE advertisement it sees."""
    global unknown_adverts
    try:
        sensor = SENSORS[mac]
    except KeyError:
        unknown_adverts += 1
        return  # phones, headphones, forklifts...

    now = time.monotonic()
    try:
        if now - last_seen[mac] < 10:
            return  # rate limit: one reading per sensor every 10 s
    except KeyError:
        pass
    last_seen[mac] = now

    reading = DECODERS[sensor["kind"]](data)
    reading["rssi"] = rssi
    publish(f"site/{sensor['room']}/{sensor['kind']}", reading)
```

I kept the `try` around the lookup only, so a `KeyError` from a decoder still surfaces instead of being counted as a foreign advert. If gateway CPU becomes a problem again, swapping that one lookup back to `.get` is a two-line change.

