```python
import csv
import hashlib
import sys

FIELDS = ("order_id", "line_no", "sku", "qty", "unit_price")


def row_fingerprint(order_id, line_no, sku, qty, unit_price):
    raw = f"{order_id}|{line_no}|{sku}|{qty}|{unit_price}"
    return hashlib.blake2b(raw.encode(), digest_size=16).hexdigest()


def load_seen(path):
    try:
        with open(path, encoding="utf-8") as fh:
            return {line.strip() for line in fh}
    except FileNotFoundError:
        return set()


def run(src, dst, seen_path):
    seen = load_seen(seen_path)
    new_keys = []
    with open(src, newline="", encoding="utf-8") as fin, \
         open(dst, "w", newline="", encoding="utf-8") as fout:
        reader = csv.DictReader(fin)
        writer = csv.DictWriter(fout, fieldnames=reader.fieldnames)
        writer.writeheader()
        for row in reader:
            key = row_fingerprint(*(row[f] for f in FIELDS))
            if key in seen:
                continue
            seen.add(key)
            new_keys.append(key)
            writer.writerow(row)
    with open(seen_path, "a", encoding="utf-8") as fh:
        fh.writelines(k + "\n" for k in new_keys)


if __name__ == "__main__":
    run(*sys.argv[1:4])
