#!/usr/bin/env python3
"""Ownership check: every tracked file must have a team in owners.json."""
import json
import subprocess
import sys


def load_owners(path="ci/owners.json"):
    # {"services/payments": "team-payments", "libs/auth": "team-identity", "infra": "team-platform"}
    with open(path) as f:
        return json.load(f)


def tracked_files():
    out = subprocess.run(["git", "ls-files"], capture_output=True, text=True, check=True)
    return out.stdout.splitlines()


def owner_for(path, owners):
    parts = path.split("/")
    # longest prefix first: services/payments/api/x.py, services/payments/api, services/payments, services
    for i in range(len(parts), 0, -1):
        prefix = "/".join(parts[:i])
        if prefix in owners:
            return owners[prefix]
    return owners.get("*")


def summarize(files, owners):
    per_team = {}
    unowned = []
    for f in files:
        team = owner_for(f, owners)
        if team is None:
            unowned.append(f)
            continue
        try:
            per_team[team] += 1
        except KeyError:
            per_team[team] = 1
    return per_team, unowned


if __name__ == "__main__":
    owners = load_owners()
    per_team, unowned = summarize(tracked_files(), owners)
    for team, n in sorted(per_team.items()):
        print(f"{team:25} {n:6d} files")
    if unowned:
        print(f"\n{len(unowned)} files without owner:")
        for f in unowned[:50]:
            print("  " + f)
        sys.exit(1)
```

**Green Notes**
- **`in` check instead of `try/except KeyError` in `owner_for`** (reduces E): the loop walks up each path, and most prefixes are not in owners.json. So the old code raised and caught an exception at almost every level, for every one of the 70k files, on every pipeline. An `in` test costs no exception. In Green Metrics Tool micro-benchmarks with 10,000,000 dict lookups and about half of the keys missing, `try/except KeyError` used ~76 J and `dict.get` ~67 J, about 12% less. An `if key in d` check performed like `dict.get`. In your job, misses are the normal case.
- **Same behavior:** I used `in` and not `owners.get(prefix)` on purpose. If an entry in owners.json is `null`, the file still counts as unowned, the same as before. A `get()` with an `is None` check would skip to the parent folder instead. The `"*"` fallback uses `get()`, which returns `None` like the old `except` branch did. The output is unchanged.
- **Counter in `summarize` left as it is:** that `try/except` misses only once per team and then always hits. When misses are rare, `try/except` is cheap, because the cost is in raising the exception.

log triage script, pegs a core for hours on the nightly logs. fix

```python
import sys
import zlib
import torch
from torch import nn
from torch.nn.functional import *

N_FEATURES = 512
LABELS = ["ok", "warn", "anomaly"]


class LineClassifier(nn.Module):
    def __init__(self):
        super().__init__()
        self.net = nn.Sequential(
            nn.Linear(N_FEATURES, 64),
            nn.ReLU(),
            nn.Dropout(0.2),
            nn.Linear(64, len(LABELS)),
        )

    def forward(self, x):
        return self.net(x)


def featurize(line):
    vec = torch.zeros(N_FEATURES)
    for tok in line.lower().split():
        vec[zlib.crc32(tok.encode()) % N_FEATURES] += 1.0
    return normalize(vec, dim=0)


def main(path):
    model = LineClassifier()
    model.load_state_dict(torch.load("models/logcls.pt", map_location="cpu"))
    flagged = 0
    with open(path, encoding="utf-8", errors="replace") as fh:
        for lineno, line in enumerate(fh, 1):
            probs = softmax(model(featurize(line)), dim=0)
            label = LABELS[int(probs.argmax())]
            if label != "ok":
                flagged += 1
                print(f"{lineno}\t{label}\t{probs.max().item():.2f}\t{line.rstrip()}")
    print(f"flagged {flagged} lines", file=sys.stderr)


if __name__ == "__main__":
    main(sys.argv[1])
```

