import re
import sys
import math
import numpy as np

NBUCKETS = 32  # bucket i covers [2**i, 2**(i+1)) microseconds


def read_durations(path):
    out = []
    with open(path, encoding="utf-8", errors="replace") as f:
        for line in f:
            m = re.match(r'^(\S+) \S+ \S+ \[[^\]]+\] "(?:GET|POST|PUT|DELETE|PATCH) [^"]*" (\d{3}) \d+ rt=(\d+\.\d+)', line)
            if m is None:
                continue
            if m.group(2).startswith("5"):
                continue
            out.append(float(m.group(3)))
    return np.array(out, dtype=np.float64)


def histogram(durations_s):
    counts = np.zeros(NBUCKETS, dtype=np.int64)
    for d in durations_s:
        us = d * 1e6
        if us < 1.0:
            b = 0
        else:
            b = int(math.log2(us))
            if b >= NBUCKETS:
                b = NBUCKETS - 1
        counts[b] += 1
    return counts


def percentile_from_hist(counts, q):
    target = q * counts.sum()
    acc = 0
    for i, c in enumerate(counts):
        acc += c
        if acc >= target:
            return 2 ** (i + 1) / 1000.0  # upper bound in ms
    return float("inf")


if __name__ == "__main__":
    durs = read_durations(sys.argv[1])
    h = histogram(durs)
    print(f"requests: {len(durs)}")
    for q in (0.5, 0.9, 0.99, 0.999):
        print(f"p{q*100:g}: <= {percentile_from_hist(h, q):.3f} ms")
