```javascript
const PAGE_SIZE = 100;
let coupons = [];
let page = 0;

async function loadCoupons() {
  const res = await fetch('/api/admin/coupons');
  if (!res.ok) {
    document.getElementById('coupon-count').textContent = 'Could not load coupons (' + res.status + ')';
    return;
  }
  coupons = await res.json();
  renderPage(0);
}

function renderPage(n) {
  const pages = Math.max(1, Math.ceil(coupons.length / PAGE_SIZE));
  page = Math.min(Math.max(n, 0), pages - 1);

  const frag = document.createDocumentFragment();
  for (const c of coupons.slice(page * PAGE_SIZE, (page + 1) * PAGE_SIZE)) {
    const tr = document.createElement('tr');
    const values = [c.code, c.discount + '%', c.used + ' / ' + c.limit, c.expires, c.note];
    for (const v of values) {
      const td = document.createElement('td');
      td.textContent = v ?? '';
      tr.appendChild(td);
    }
    frag.appendChild(tr);
  }
  document.getElementById('coupon-body').replaceChildren(frag);

  document.getElementById('coupon-count').textContent =
    coupons.length + ' coupons, page ' + (page + 1) + ' of ' + pages;
}

document.getElementById('prev').addEventListener('click', () => renderPage(page - 1));
document.getElementById('next').addEventListener('click', () => renderPage(page + 1));

loadCoupons();
```

