```python
import math


class LatencyHistogram:
    """Power-of-two latency buckets from access log lines: ip method ms"""

    def __init__(self, max_bucket=20):
        self.max_bucket = max_bucket
        self.counts = [0] * (max_bucket + 1)
        self.total_ms = 0.0
        self.skipped = 0

    def feed(self, path):
        f = open(path)
        for line in f:
            parts = line.split()
            if len(parts) < 3:
                self.skipped += 1
                continue
            try:
                ms = float(parts[2])
            except:
                self.skipped += 1
                continue
            if ms < 1:
                bucket = 0
            else:
                bucket = int(math.log2(ms))
            if bucket > self.max_bucket:
                bucket = self.max_bucket
            self.counts[bucket] += 1
            self.total_ms += ms

    def mean(self):
        n = sum(self.counts)
        return self.total_ms / n if n else 0.0
