```python
import threading
import time

MAX_PER_ROOM = 1000


class RoomStore:
    def __init__(self):
        self._rooms = {}
        self._lock = threading.Lock()

    def add_message(self, room, user, text):
        with self._lock:
            msgs = self._rooms.setdefault(room, [])
            msg = {"id": len(msgs) + 1, "user": user, "text": text, "ts": time.time()}
            msgs.insert(0, msg)
            if len(msgs) > MAX_PER_ROOM:
                msgs.pop()
        return msg

    def latest(self, room, limit=50):
        with self._lock:
            return self._rooms.get(room, [])[:limit]


def get_messages(store, room, limit_param):
    limit = int(limit_param or 50)
    return {"room": room, "messages": store.latest(room, limit)}
