    """Called from the SIGHUP handler after finance edits the file."""
    global VAT_RULES
    with open(RULES_PATH) as f:
        VAT_RULES = json.load(f)


def vat_rate(country: str, category: str) -> Decimal:
    best = None
    for rule in VAT_RULES:
        if rule["country"] != country:
            continue
        if category in rule["categories"] or "*" in rule["categories"]:
            # most specific rule = shortest category list
            if best is None or len(rule["categories"]) < len(best["categories"]):
                best = rule
    if best is None:
        raise KeyError(f"no VAT rule for {country}/{category}")
    return Decimal(best["rate"])


def cart_totals(cart: dict) -> dict:
    net = Decimal("0")
    vat = Decimal("0")
    for line in cart["lines"]:
        rate = vat_rate(cart["ship_to"], line["category"])
        line_net = Decimal(str(line["unit_price"])) * line["qty"]
        net += line_net
        vat += line_net * rate
    vat = vat.quantize(Decimal("0.01"))
    return {"net": net, "vat": vat, "gross": net + vat}
```

